// Thresholds live in env so ops can tune them without editing the workflow.
const complianceTarget = Number($env.SLA_COMPLIANCE_THRESHOLD || 90);
const backlogLimit = Number($env.BACKLOG_THRESHOLD || 350);
const cooldownMin = Number($env.ALERT_COOLDOWN_MINUTES || 120);

const s = $input.first().json;
const now = new Date(s.evaluated_at);
const cooledDown = (last) => !last || (now - new Date(last)) / 60000 >= cooldownMin;
const num = (v) => (v === null || v === undefined ? null : Number(v));

const alerts = [];
const compliance = num(s.sla_compliance_pct_24h);
const decided = num(s.sla_met_24h) + num(s.sla_breached_24h);
if (compliance !== null && compliance < complianceTarget && cooledDown(s.sla_compliance_last_sent_at)) {
  alerts.push({
    alert_type: 'sla_compliance',
    alert_key: 'rolling_24h',
    severity: compliance < complianceTarget - 10 ? 'critical' : 'warning',
    line: `First-response SLA compliance (rolling 24h) is ${compliance}%, below the ${complianceTarget}% target: ${num(s.sla_breached_24h)} of ${decided} decided tickets breached.`,
  });
}

const backlog = num(s.open_backlog);
if (backlog > backlogLimit && cooledDown(s.backlog_last_sent_at)) {
  alerts.push({
    alert_type: 'backlog',
    alert_key: 'open_backlog',
    severity: backlog > backlogLimit * 1.25 ? 'critical' : 'warning',
    line: `Open ticket backlog is ${backlog} (limit ${backlogLimit}); ${num(s.open_backlog_urgent_high)} of them are urgent/high priority.`,
  });
}

for (const u of s.new_urgent_breaches || []) {
  const waited = Math.round(Number(u.minutes_waited));
  const state = u.first_response_at ? `answered after ${waited} min` : `STILL UNANSWERED after ${waited} min`;
  alerts.push({
    alert_type: 'urgent_breach',
    alert_key: u.ticket_id,
    severity: 'critical',
    line: `URGENT ${u.ticket_id} - ${u.company_name} (${u.segment}), ${u.category_name} / ${u.subcategory_name} via ${u.channel}: ${state} (target ${u.first_response_target_minutes} min). Agent: ${u.agent_name}, ${u.team_name}.`,
  });
}

if (alerts.length === 0) {
  return [];
}

const critical = alerts.some((a) => a.severity === 'critical');
const metrics = {
  evaluated_at: s.evaluated_at,
  data_loaded_through: s.data_loaded_through,
  sla_compliance_pct_24h: compliance,
  tickets_created_24h: num(s.tickets_created_24h),
  open_backlog: backlog,
  urgent_breached_24h: num(s.urgent_breached_24h),
  urgent_breached_open: num(s.urgent_breached_open),
};
const counts = alerts.reduce((acc, a) => ({ ...acc, [a.alert_type]: (acc[a.alert_type] || 0) + 1 }), {});
const subject = `[${critical ? 'CRITICAL' : 'WARNING'}] Customer Care SLA alert - ${Object.entries(counts).map(([k, v]) => `${k} x${v}`).join(', ')}`;
const text = [
  `Customer Care SLA monitor fired ${alerts.length} alert(s) at ${s.evaluated_at} (data loaded through ${s.data_loaded_through}).`,
  '',
  ...alerts.map((a) => `- [${a.severity.toUpperCase()}] ${a.line}`),
  '',
  `Snapshot: compliance 24h = ${compliance ?? 'n/a'}%, tickets created 24h = ${metrics.tickets_created_24h}, open backlog = ${backlog}, urgent breaches 24h = ${metrics.urgent_breached_24h} (${metrics.urgent_breached_open} still open).`,
  `Dashboard: ${$env.DASHBOARD_URL}  |  Pipeline: ${$env.AIRFLOW_URL}`,
].join('\n');

return [{
  json: {
    subject,
    text,
    slack_enabled: Boolean($env.SLACK_WEBHOOK_URL),
    alerts: alerts.map((a) => ({ alert_type: a.alert_type, alert_key: a.alert_key, severity: a.severity, message: a.line })),
    metrics,
  },
}];

// One alert_log row per fired alert; also the dedup/cooldown memory for the next evaluation.
const e = $('Evaluate thresholds').first().json;
const channels = ['email', 'log'].concat(e.slack_enabled ? ['slack'] : []);
return e.alerts.map((a) => ({
  json: { ...a, metrics: JSON.stringify(e.metrics), channels: `{${channels.join(',')}}` },
}));
